'use strict';

/**
 * Client-side art.
 *
 * The portraits are generated by the server from `src/art/`, so this module has
 * one job: turn "which unit is this" into a URL, and make sure the picture is
 * already in the browser cache before it is needed.
 *
 * Why `<img>` and not inlined SVG: the same character appears in the battle row,
 * the turn order, the party strip and the party screen at four different sizes.
 * An `<img>` is cached once by URL and reused, whereas inlining would put a
 * 45 KB copy of the same drawing in the DOM four times — and would also mean
 * resolving duplicate `clipPath` ids across copies.
 *
 * Art is decoration. Every function here degrades to "no picture" rather than
 * throwing, because a missing portrait must never be the reason a battle screen
 * fails to render.
 */

const Art = {
  /** Manifest entries, keyed `kind/id`. */
  entries: new Map(),

  loaded: false,
  loading: null,

  /** Preloaded URLs, so `preload` does not re-request the same thing. */
  warmed: new Set(),

  // =======================================================================
  // Loading
  // =======================================================================

  /**
   * Fetch the manifest.
   *
   * Memoised: `Main.boot` and the first battle both want it, and the second
   * caller should await the first request rather than issue another.
   */
  load() {
    if (this.loaded) return Promise.resolve(this);
    if (this.loading) return this.loading;

    this.loading = fetch('/api/art')
      .then((res) => res.json())
      .then((data) => {
        for (const entry of data.entries || []) {
          this.entries.set(`${entry.kind}/${entry.id}`, entry);
        }
        this.loaded = true;
        return this;
      })
      .catch(() => {
        // Offline, or the server predates the art routes. The game still runs;
        // the portraits fall back to the letter sigil.
        this.loading = null;
        return this;
      });

    return this.loading;
  },

  // =======================================================================
  // Lookup
  // =======================================================================

  has(kind, id) {
    return this.entries.has(`${kind}/${id}`);
  },

  get(kind, id) {
    return this.entries.get(`${kind}/${id}`) || null;
  },

  /**
   * Map a battle unit id to a piece of art.
   *
   * Summoned adds carry a suffix (`rotgrub_0`, `ash_husk_2`), so the lookup
   * tries the exact id first and then the id with the last segment removed.
   * That is the same rule `spriteFor` used for the letter sigils, kept because
   * it is the rule the engine actually produces ids by.
   */
  resolve(id, side) {
    const data = State.data || {};
    const chars = data.characters || [];
    const enemies = data.enemies || [];
    const raw = String(id == null ? '' : id);
    const base = raw.split('_').slice(0, -1).join('_') || raw;

    const char = chars.find((c) => c.id === raw) || chars.find((c) => c.id === base);
    if (char && this.has('character', char.id)) return { kind: 'character', id: char.id };

    const enemy = enemies.find((e) => e.id === raw) || enemies.find((e) => e.id === base);
    if (enemy && this.has('enemy', enemy.id)) return { kind: 'enemy', id: enemy.id };

    // Last resort: an NPC (dialogue portraits go through here too).
    if (this.has('npc', raw)) return { kind: 'npc', id: raw };
    if (this.has('npc', base)) return { kind: 'npc', id: base };

    return side === 'enemy' ? { kind: null, id: null } : { kind: null, id: null };
  },

  // =======================================================================
  // URLs
  // =======================================================================

  url(kind, id, options = {}) {
    const query = new URLSearchParams();
    if (options.view) query.set('view', options.view);
    if (options.expression && options.expression !== 'neutral') {
      query.set('expression', options.expression);
    }
    if (options.phase && Number(options.phase) >= 2) query.set('phase', String(options.phase));
    if (options.plain) query.set('plain', '1');
    const qs = query.toString();
    return `/art/${kind}/${id}.svg${qs ? `?${qs}` : ''}`;
  },

  /**
   * An `<img>` for a piece of art, or `null` when there is none.
   *
   * Returning `null` rather than a placeholder keeps the call sites honest:
   * they have to decide what the fallback looks like, and the fallback differs
   * (a letter sigil in a circle, a coloured chip, nothing at all).
   */
  image(kind, id, options = {}) {
    if (!kind || !id || !this.has(kind, id)) return null;
    const img = document.createElement('img');
    img.className = options.className || 'art-img';
    img.src = this.url(kind, id, options);
    img.alt = options.alt || '';
    img.draggable = false;
    img.decoding = 'async';
    // Portraits are almost always above the fold in a battle; lazy loading
    // would make them pop in after the animation starts.
    img.loading = options.lazy ? 'lazy' : 'eager';
    if (options.size) {
      img.width = options.size;
      img.height = options.size;
    }
    return img;
  },

  // =======================================================================
  // Unit helpers
  // =======================================================================

  /**
   * Which face a unit should be wearing.
   *
   * Hurt at low health is the one expression change worth a network request:
   * it is information the player can act on, and it costs nothing to notice.
   */
  expressionFor(unit) {
    if (!unit) return 'neutral';
    if (unit.down) return 'hurt';
    if (typeof unit.hpRatio === 'number' && unit.hpRatio <= 0.3) return 'hurt';
    return 'neutral';
  },

  /** Enemy art phase. Only the boss has more than one. */
  phaseFor(unit) {
    const p = unit && Number(unit.phase);
    return Number.isFinite(p) && p >= 2 ? 2 : 1;
  },

  // =======================================================================
  // Warming
  // =======================================================================

  /**
   * Start fetching a set of URLs now.
   *
   * Called when a battle begins, before the first render, so the first frame
   * already has faces. The `Image` objects are not kept: the browser's cache is
   * the point, and holding references would just pin memory.
   */
  preload(urls) {
    for (const url of urls) {
      if (!url || this.warmed.has(url)) continue;
      this.warmed.add(url);
      const img = new Image();
      img.decoding = 'async';
      img.src = url;
    }
  },

  /**
   * Warm every portrait a battle will need.
   *
   * Both expressions, because switching to `hurt` mid-fight is exactly when a
   * load delay would be most visible.
   */
  preloadBattle(view) {
    const battle = (view && view.battle) ? view.battle : view;
    if (!battle) return;
    const urls = [];
    for (const unit of [...(battle.allies || []), ...(battle.enemies || [])]) {
      const target = this.resolve(unit.id, unit.side);
      if (!target.kind) continue;
      for (const expression of ['neutral', 'hurt']) {
        urls.push(this.url(target.kind, target.id, {
          view: 'bust', expression, phase: this.phaseFor(unit), plain: true,
        }));
      }
    }
    this.preload(urls);
  },

  /** Warm the full-body art for a set of character ids. */
  preloadParty(charIds) {
    this.preload(charIds.map((id) => this.url('character', id, { view: 'full' })));
  },
};

if (typeof window !== 'undefined') window.Art = Art;
